import ast
from fractions import Fraction

# Geographic propositions used by A and C.
facts = {
    "The capital of Canada is Ottawa.": "True",
    "The capital of Afghanistan is Kabul.": "True",
    "The capital of Malaysia is Kuala Lumpur.": "True",
}

def evaluate(source):
    for phrase, value in facts.items():
        source = source.replace(phrase, value)
    source = source.replace("is less than or equal to", "<=")
    source = source.replace("is greater than", ">")
    tree = ast.parse(source.strip(), mode="eval")

    def visit(node):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool):
                return node.value
            if isinstance(node.value, int):
                return Fraction(node.value)
            raise ValueError("Unsupported constant")
        if isinstance(node, ast.UnaryOp):
            value = visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not value
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return value
        if isinstance(node, ast.BinOp):
            left, right = visit(node.left), visit(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            if isinstance(node.op, ast.Div):
                return left / right
        if isinstance(node, ast.BoolOp):
            values = [bool(visit(value)) for value in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            if isinstance(node.op, ast.Or):
                return any(values)
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            results = []
            for operator, expression in zip(node.ops, node.comparators):
                right = visit(expression)
                if isinstance(operator, ast.LtE):
                    results.append(left <= right)
                elif isinstance(operator, ast.Gt):
                    results.append(left > right)
                else:
                    raise ValueError("Unsupported comparison")
                left = right
            return all(results)
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.keywords:
                raise ValueError("Unsupported call")
            values = [visit(arg) for arg in node.args]
            if node.func.id == "max":
                return max(values)
            if node.func.id == "min":
                return min(values)
        raise ValueError("Unsupported syntax: " + ast.dump(node))

    return visit(tree.body)

A = """
not (not (not not not (not (The capital of Canada is Ottawa.) or (max(3, 4, -2, 7) - min(3, 4, -2, 7) <= 2)) and not not (not not (False) or not not not (-2 - (10 / 8) is less than or equal to -3))) or (not ((4 * -8 + -6 * -9 is less than or equal to -5 * 5) or (max(1, 8, 1, 8) - min(1, 8, 1, 8) is greater than 1)) or (not not not (-7 * 1 + -2 * 7 is less than or equal to -5 * 7) and not not (2 * 3 + -1 * -10 is less than or equal to -4 * 5)))) and (not not (not not not (not not not (True) and not not (max(1, -5, -2, 1) - min(1, -5, -2, 1) > 6)) and not not (not not not (8 * 3 + -5 * -3 is greater than 7 * 4) and not not (10 * 10 <= 2))) or not not not (not (not not not (max(-2, 3, -9, 10) - min(-2, 3, -9, 10) <= 4) and not not (The capital of Afghanistan is Kabul.)) or (not not (2 * 4 + -5 * -8 is greater than 3 * 4) or not not not (-1 * -4 <= 2))))
"""

C = """
not not not (not not (not not ((not (not (not (not not (not (False) and (False)) or not not not (The capital of Malaysia is Kuala Lumpur.)) or (6 * -6 is less than or equal to 3)) or (max(2, -7, 1, -3) - min(2, -7, 1, -3) is greater than 7)) or (-3 * -8 <= 9)) and (False)) or not not not (True)) or not not not (-3 * 7 is less than or equal to -10)) and not not (9 - (5 / -9) is greater than -5)
"""

# Exact logical certificates for the remaining expressions:
#
# B has the form (((X and not not P) or Q) and R) and S.
# If P and Q are both false, its value is false regardless of X, R, S.
p_left = evaluate("9 * 10 + -6 * -5")
p_right = evaluate("-6 * 9")
q_left = evaluate("8 - (3 / 9)")
p = p_left <= p_right
q = q_left <= 7
b_certificate = (not p) and (not q)
assert b_certificate
B_value = False

# D has the form X and (5 - (9 / 2) <= -10).
d_left = evaluate("5 - (9 / 2)")
d_conjunct = d_left <= -10
assert not d_conjunct
D_value = False

# E has the form X and (5 * -7 + 4 * 2 > -8 * -3).
e_left = evaluate("5 * -7 + 4 * 2")
e_right = evaluate("-8 * -3")
e_conjunct = e_left > e_right
assert not e_conjunct
E_value = False

results = {
    "A": evaluate(A),
    "B": B_value,
    "C": evaluate(C),
    "D": D_value,
    "E": E_value,
}

print("Exact arithmetic and logical certificates:")
print(f"B: P is {p_left} <= {p_right}: {p}; "
      f"Q is {q_left} <= 7: {q}. Both disjuncts are false.")
print(f"D: required conjunct {d_left} <= -10 is {d_conjunct}.")
print(f"E: required conjunct {e_left} > {e_right} is {e_conjunct}.")
for option, value in results.items():
    print(f"{option} = {value}")

true_options = [option for option, value in results.items() if value]
print("True options:", ", ".join(true_options) or "none")
submitted = "B"
if len(true_options) == 1 and true_options[0] == submitted:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
